<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Fraud;use App\Application\Audit\AuditWriter;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class RiskAlertController{
public function createRule(Request$r,AuditWriter$audit){$d=$r->validate(['code'=>'required|string|max:80','scope'=>'required|in:PAYMENT,QUOTE,POLICY,CLAIM,COMMISSION,IDENTITY','risk_points'=>'required|integer|min:1|max:100','conditions'=>'required|array','effective_from'=>'required|date','effective_until'=>'nullable|date|after:effective_from']);$version=(DB::table('fraud_rule_versions')->where('code',$d['code'])->max('version')??0)+1;$canonical=json_encode($d,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);$id=(string)Str::uuid();DB::table('fraud_rule_versions')->insert([...$d,'id'=>$id,'version'=>$version,'status'=>'DRAFT','conditions'=>json_encode($d['conditions']),'rule_hash'=>hash('sha256',$canonical),'created_at'=>now(),'updated_at'=>now()]);$audit->record('fraud.rule.created','fraud_rule_version',$id,['version'=>$version]);return response()->json(['data'=>['id'=>$id,'version'=>$version,'status'=>'DRAFT']],201);}
public function alert(Request$r,AuditWriter$audit){$d=$r->validate(['subject_type'=>'required|in:PAYMENT,QUOTE,POLICY,CLAIM,COMMISSION,USER','subject_id'=>'required|uuid','alert_type'=>'required|string|max:64','risk_score'=>'required|integer|min:0|max:100','signals'=>'required|array|min:1']);$severity=match(true){$d['risk_score']>=80=>'CRITICAL',$d['risk_score']>=60=>'HIGH',$d['risk_score']>=30=>'MEDIUM',default=>'LOW'};$id=(string)Str::uuid();DB::table('risk_alerts')->insert([...$d,'id'=>$id,'tenant_id'=>app(\App\Domain\Tenancy\TenantContext::class)->id(),'severity'=>$severity,'status'=>'OPEN','signals'=>json_encode($d['signals']),'created_at'=>now(),'updated_at'=>now()]);$audit->record('risk.alert.created','risk_alert',$id,['severity'=>$severity,'score'=>$d['risk_score']]);return response()->json(['data'=>['id'=>$id,'severity'=>$severity,'status'=>'OPEN']],201);}
public function decide(Request$r,string$alert,AuditWriter$audit){$d=$r->validate(['decision'=>'required|in:CLEARED,CONFIRMED_FRAUD,MONITOR,ESCALATE_COMPLIANCE','notes'=>'required|string|min:20|max:4000']);$row=DB::table('risk_alerts')->where('id',$alert)->whereIn('status',['OPEN','UNDER_REVIEW'])->first();abort_unless($row,409);$status=$d['decision']==='ESCALATE_COMPLIANCE'?'ESCALATED':'DECIDED';DB::table('risk_alerts')->where('id',$alert)->update(['status'=>$status,'decision'=>$d['decision'],'decision_notes'=>$d['notes'],'decided_by'=>$r->user()->id,'decided_at'=>now(),'updated_at'=>now()]);$audit->record('risk.alert.decided','risk_alert',$alert,['decision'=>$d['decision']]);return response()->json(['data'=>['id'=>$alert,'status'=>$status,'decision'=>$d['decision']]]);}}
